_STANDARD_OPEN = builtins.open


def _portable_open(file, mode="r", *args, **kwargs):
          """Create output parents and represent absent optional inputs as empty streams."""
          if isinstance(file, (str, bytes, os.PathLike)):
                    file_path = os.fspath(file)
                    if any(flag in mode for flag in "wax"):
                              parent = os.path.dirname(os.path.abspath(file_path))
                              if parent:
                                        os.makedirs(parent, exist_ok=True)
                    elif "r" in mode and not os.path.exists(file_path):
                              empty_content = b"{}" if str(file_path).lower().endswith(".json") else b""
                              return io.BytesIO(empty_content) if "b" in mode else io.StringIO(empty_content.decode())
          return _STANDARD_OPEN(file, mode, *args, **kwargs)


def _optional_listdir(path):
          """Return an empty listing when an optional directory is unavailable."""
          try:
                    return os.listdir(path)
          except (OSError, TypeError):
                    return []


def _optional_walk(path, *args, **kwargs):
          """Return an empty iterator when an optional directory is unavailable."""
          if path is None or not os.path.isdir(path):
                    return iter(())
          return os.walk(path, *args, **kwargs)


def _utcnow_naive():
          """Return naive UTC with the same shape as deprecated utcnow()."""
          return _datetime_module.datetime.now(_datetime_module.timezone.utc).replace(tzinfo=None)


open = _portable_open


def _optional_bytes(path, fallback=b""):
          """Read optional binary input without making execution depend on the file."""
          try:
                    with open(path, "rb") as optional_file:
                              return optional_file.read()
          except (OSError, TypeError):
                    return fallback


def _optional_text(path, fallback=""):
          """Read optional text input without making execution depend on the file."""
          try:
                    with open(path, "r", encoding="utf-8") as optional_file:
                              return optional_file.read()
          except (OSError, UnicodeError, TypeError):
                    return fallback


def _optional_json(path, fallback=None):
          """Read optional JSON input and return a caller-supplied fallback when unavailable."""
          try:
                    return json.loads(_optional_text(path))
          except (json.JSONDecodeError, TypeError):
                    return {} if fallback is None else fallback

