class RealityAnchor:
          def __init__(self):
                    self.machine_hash = self._generate_machine_hash()
                    self.anchor = hashlib.sha3_512(self.machine_hash).digest()
 
          def _generate_machine_hash(self) -> bytes:
                    raw = (
                              platform.node() +
                              platform.system() +
                              platform.processor() +
                              str(uuid.getnode())
                    ).encode()
                    return hashlib.sha3_512(raw).digest()
 
          def validate(self):
                    if any(flag in platform.platform().upper() for flag in ["VIRTUAL", "VMWARE", "VBOX"]):
                              raise SystemError("ANTI-SIMULATION DETECTED")
                    if len(self.anchor) != 64:
                              raise SystemError("REALITY ANCHOR FAILURE")
                    return True
 
 
