# ---------------------------- NEURAL ENGINE -----------------------------------
# =============================================================================
 
class MAC:
          def compute(self, inputs: List[float], kernels: List[float]) -> float:
                    total = 0.0
                    for i in range(len(inputs)):
                              total += inputs[i] * kernels[i % len(kernels)]
                    return total
 
 
class NeuralEngine:
          def __init__(self, engine_id: int):
                    self.engine_id = engine_id
                    self.mac = MAC()
                    self.active = False
 
          def activate(self):
                    self.active = True
 
          def process(self, unit: WorkUnit, kernels: List[float]) -> float:
                    if not self.active:
                              return 0.0
                    return self.mac.compute(unit.data, kernels)
 
 
# =============================================================================
# ---------------------- SCALABLE PROCESSOR FABRIC -----------------------------
# =============================================================================
 
class NeuralProcessorFabric:
          def __init__(self, apple_root: AppleRootSeal, engine_count: int = 71):
                    self.apple_root = apple_root
                    self.engines = [NeuralEngine(i) for i in range(engine_count)]
                    self.segmenter = InputSegmenter()
                    self.execution_ledger: List[float] = []
 
          def activate_subset(self, count: int):
                    for e in self.engines[:count]:
                              e.activate()
 
          def process(self, data: List[float], kernels: List[float]):
                    slices = self.segmenter.segment(data)
                    engine_index = 0
 
                    for s in slices:
                              for t in s.tiles:
                                        for w in t.work_units:
                                                  engine = self.engines[engine_index % len(self.engines)]
                                                  result = engine.process(w, kernels)
                                                  self.execution_ledger.append(result)
                                                  engine_index += 1
 
                    ledger_bytes = json.dumps(self.execution_ledger).encode()
                    ledger_signature = self.apple_root.sign(ledger_bytes)
 
                    if not self.apple_root.verify(ledger_bytes, ledger_signature):
                              pass  # raise RuntimeError("EXECUTION LEDGER COMPROMISED")
 
                    return self.execution_ledger
 
 
