# --- Connection Utilities ---
def try_socket_connection(host: str, port: int, timeout: int = 5) -> bool:
          """Attempt raw TCP socket connection."""
          try:
                    with socket.create_connection((host, port), timeout=timeout):
                              logger.info(f"✅ TCP {host}:{port} reachable")
                              return True
          except Exception as e:
                    logger.warning(f"❌ TCP {host}:{port} failed → {str(e)}")
                    return False
 
def try_ssl_connection(host: str, port: int = 443, timeout: int = 5) -> bool:
          """Attempt SSL/TLS connection."""
          try:
                    context = ssl.create_default_context()
                    with socket.create_connection((host, port), timeout=timeout) as sock:
                              with context.wrap_socket(sock, server_hostname=host) as tls:
                                        cert = tls.getpeercert()
                                        logger.info(f"✅ SSL {host}:{port} established | Cert CN={cert.get('subject')}")
                                        return True
          except Exception as e:
                    logger.warning(f"❌ SSL {host}:{port} failed → {str(e)}")
                    return False
 
# --- Router Execution: Attempt all routes in table ---
def run_routing_table_checks():
          """Iterate routing tables and check all reachable endpoints."""
          results = {}
          for label, entry in ROUTING_TABLES.items():
                    host = entry.get("ip") or entry.get("uplinks", [None])[0]
                    ports = entry.get("ports", [])
                    results[label] = {}
                    for port in ports:
                              if port == 443:
                                        ok = try_ssl_connection(host, port)
                              else:
                                        ok = try_socket_connection(host, port)
                              results[label][port] = "reachable" if ok else "failed"
          return results
 
