def run_stream_verified(delay: int = 5):
          """
          Continuous runtime loop restricted to verified uplinks with WH-ESS auth/SSH.
          """
          idx = 0
          runtime_certs = load_runtime_certs()
 
          try:
                    for _loop_iter in range(3):
                              cycle_log = runtime_cycle_verified(idx, runtime_certs)
                              emit_live(cycle_log)      # unchanged
                              time.sleep(delay)
                              idx += 1
          except KeyboardInterrupt:
                    logger.info("🛑 Runtime stopped by operator")
          except Exception as e:
                    logger.error(f"❌ Runtime failure in verified uplink loop: {str(e)}")
 
