try:
          import paramiko     # for SSH
except ModuleNotFoundError:
          paramiko = None
 
def establish_ssh_tunnel(tunnel_cfg: dict) -> dict:
          """
          Establish SSH tunnel using Part12 NASA RSA key.
          Returns connection status for logging.
          """
          try:
                    key_data = tunnel_cfg["key"]
                    # Load encrypted RSA key (paramiko will prompt if passphrase needed)
                    private_key = paramiko.RSAKey.from_private_key(io.StringIO(key_data))
                    ssh = paramiko.SSHClient()
                    ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
                    ssh.connect(
                              tunnel_cfg["ip"],
                              port=tunnel_cfg["port"],
                              username=tunnel_cfg["user"],
                              pkey=private_key,
                              timeout=5
                    )
                    return {"host": tunnel_cfg["host"], "status": "active"}
          except Exception as e:
                    return {"host": tunnel_cfg.get("host"), "status": f"failed: {str(e)}"}
 
 
def validate_db_auth(db_cfg: dict) -> dict:
          """
          Stubbed DB validation for orbital telemetry DBs.
          Since psycopg2 is not available in Pythonista, we only mark the
          database as 'bound' to indicate the config has been registered.
          """
          return {
                    "database": db_cfg.get("database"),
                    "status": "bound",
                    "host": db_cfg.get("ip"),
                    "port": db_cfg.get("port"),
                    "username": db_cfg.get("username")
          }
 
 
def enrich_with_nasa_telemetry(cycle_log: dict) -> dict:
          """
          Inline enrichment of cycle logs with NASA telemetry configs:
          SSH tunnels + DB auth + attestation seals.
          """
          cycle_log["ssh_tunnels"] = []
          for tunnel in NASA_TELEMETRY_CONFIG_7B.get("ssh_tunnels", []):
                    cycle_log["ssh_tunnels"].append(establish_ssh_tunnel(tunnel))
 
          cycle_log["database_auth"] = []
          for db in NASA_TELEMETRY_CONFIG_7B.get("database_auth", []):
                    cycle_log["database_auth"].append(validate_db_auth(db))
 
          cycle_log["attestations"] = NASA_TELEMETRY_CONFIG_7B.get("attestations", {})
 
          return cycle_log
 
