def fetch_nasa_telemetry_ext(config: dict) -> dict:
          """
          Actively query NASA extended orbital telemetry endpoints from Tear.txt config.
          Emits live freq, strength, objects directly from TPM/uplink response.
          """
          telemetry = {"status": "initializing"}
 
          try:
                    # Pull signal strength (X-band) from endpoint
                    endpoint = config["orbital_frequency_monitoring"][0]["signal_strength_endpoint"]
                    resp = requests.get(endpoint, timeout=10, verify=False, headers={
                              "Authorization": f"Bearer {config['client_auth']['api_key']}"
                    })
                    resp.raise_for_status()
 
                    # Expecting live JSON payload from TPM/uplink
                    data = resp.json()
                    telemetry.update({
                              "freq": data.get("FREQ"),
                              "strength": data.get("STRENGTH"),
                              "objects": data.get("OBJECTS"),
                              "status": "active"
                    })
 
          except Exception as e:
                    logger.error(f"❌ NASA EXT telemetry fetch failed: {str(e)}")
                    telemetry["status"] = "unreachable"
 
          return telemetry
 
 
