logger = logging.getLogger("USSS-APPLE-2025-EXECUTION-7C")
 
def fetch_nasa_telemetry():
          """
          Execute live orbital telemetry fetches from NASA config endpoints.
          Returns parsed JSON or raw telemetry per band/object.
          """
          results = {"orbital": {}, "objects": {}}
 
          try:
                    # Frequency monitoring (per band)
                    for band in NASA_TELEMETRY_CONFIG_7B["orbital_frequency_monitoring"]:
                              url = band["endpoint"]
                              try:
                                        resp = requests.get(
                                                  url,
                                                  headers={"Authorization": f"Bearer {NASA_TELEMETRY_CONFIG_7B['client_auth']['api_key']}"},
                                                  timeout=10, verify=False
                                        )
                                        resp.raise_for_status()
                                        results["orbital"][band["band"]] = resp.json()
                                        logger.info(f"📡 {band['band']} telemetry pulled from {url}")
                              except Exception as e:
                                        logger.warning(f"❌ {band['band']} telemetry fetch failed: {str(e)}")
                                        results["orbital"][band["band"]] = {}
 
                    # Space object tracking
                    obj_cfg = NASA_TELEMETRY_CONFIG_7B["space_objects_monitoring"]
                    if obj_cfg["enabled"]:
                              try:
                                        resp = requests.get(
                                                  obj_cfg["tracking_endpoint"],
                                                  headers={"Authorization": f"Bearer {NASA_TELEMETRY_CONFIG_7B['client_auth']['api_key']}"},
                                                  timeout=10, verify=False
                                        )
                                        resp.raise_for_status()
                                        results["objects"] = resp.json()
                                        logger.info(f"🛰️ Space objects telemetry pulled from {obj_cfg['tracking_endpoint']}")
                              except Exception as e:
                                        logger.warning(f"❌ Space objects telemetry fetch failed: {str(e)}")
                                        results["objects"] = {}
          except Exception as e:
                    logger.error(f"❌ NASA telemetry fetch error: {str(e)}")
 
          return results
 
