class PDP8Opcode(Enum):
    """PDP-8/IX base instruction set opcodes (3-bit, octal)."""
    AND = 0o0000  # Logical AND
    TAD = 0o1000  # Two's complement ADD
    ISZ = 0o2000  # Increment and Skip if Zero
    DCA = 0o3000  # Deposit and Clear AC
    JMS = 0o4000  # Jump to Subroutine
    JMP = 0o5000  # Jump
    IOT = 0o6000  # Input/Output Transfer
    OPR = 0o7000  # Operate (microcoded)


class PDP8ExtendedSymbol(Enum):
    """Extended symbols from Page 1 of the MIT RADAR PDP-8/IX kernel."""
    # EAE (Extended Arithmetic Element)
    MUY = 0o7405
    DVI = 0o7407
    NMI = 0o7411
    SHL = 0o7413
    MQA = 0o7501
    ASR = 0o7415
    LSR = 0o7417
    MQL = 0o7421
    SCA = 0o7441
    CAM = 0o7621
    SCL = 0o7403
    XAM = 0o7521
    # Memory Extension
    CDF = 0o6201
    CIF = 0o6202
    RDF = 0o6214
    RIF = 0o6224
    RMF = 0o6244
    RIB = 0o6234
    # A/D Converter
    ADSF = 0o6531
    ADCV = 0o6532
    ADRB = 0o6534
    ADCC = 0o6541
    ADSC = 0o6542
    ADIC = 0o6544
    # Scope Control
    SCER = 0o6051
    SCLX = 0o6052
    SCIX = 0o6054
    SCLIX = 0o6056
    SCSE = 0o6061
    SCLY = 0o6062
    SCIY = 0o6064
    SCLIY = 0o6066
    # External Switch Register
    ESR = 0o6360


@dataclass
class PDP8Register:
    """PDP-8/IX CPU register state."""
    AC: int = 0       # Accumulator (12-bit)
    PC: int = 0o0200  # Program Counter
    MQ: int = 0       # Multiplier Quotient
    SR: int = 0       # Switch Register
    IF_: int = 0      # Instruction Field
    DF: int = 0       # Data Field
    SF: int = 0       # Save Field
    LK: int = 0       # Link bit
    IB: int = 0       # Interrupt Buffer
    UB: int = 0       # User Buffer
    UF: int = 0       # User Flag


@dataclass
class ProcessControlBlock:
    """Process Control Block as defined in the MIT RADAR kernel (Page 5).
    Structure: PCBPC, PCBAC, PCBMQ, PCBLXM, PCBX, PCBMF"""
    pcb_pc: int = 0     # Saved Program Counter
    pcb_ac: int = 0     # Saved Accumulator
    pcb_mq: int = 0     # Saved MQ Register
    pcb_lxm: int = 0    # Saved Link/XMode
    pcb_x: int = 0      # Saved Index
    pcb_mf: int = 0     # Saved Memory Field


class InterruptHandler:
    """Non-DECtape Interrupt Handler from Page 5 of the MIT RADAR kernel.
    Implements INTL1/INTL2 interrupt entry and PCB update logic."""

    def __init__(self):
        self.isvpc: int = 0
        self.isvac: int = 0
        self.isvmq: int = 0
        self.isvx: int = 0
        self.isvlxm: int = 0
        self.isvmf: int = 0
        self.ihaddr: int = 0
        self.ihtab: List[int] = [0] * 64  # Interrupt handler table

    def intl1_save_context(self, regs: PDP8Register) -> None:
        """INTL1: Save AC, memory fields, PC on interrupt entry."""
        self.isvac = regs.AC
        self.isvmf = (regs.IF_ << 3) | regs.DF
        self.isvpc = regs.PC

    def intl2_read_interrupt_address(self) -> int:
        """INTL2: Read interrupt address until two consecutive readings match.
        Returns the validated interrupt handler address."""
        reading1 = self.ihaddr
        reading2 = self.ihaddr
        while reading1 != reading2:
            reading1 = reading2
            reading2 = self.ihaddr
        return reading1

    def update_pcb(self, pcb: ProcessControlBlock) -> None:
        """UPPCB: Update Process Control Block. Enter with X->PCB, mode 6."""
        pcb.pcb_pc = self.isvpc
        pcb.pcb_ac = self.isvac
        pcb.pcb_mq = self.isvmq
        pcb.pcb_lxm = self.isvlxm
        pcb.pcb_x = self.isvx
        pcb.pcb_mf = self.isvmf


