@dataclass
class KernelPage:
    """Represents a single page of the MIT RADAR PDP-8/IX kernel source listing."""
    page_index: int
    filename: str
    file_size_bytes: int
    sha512_hash: str
    tpm119_pcr_extension: str
    dod_pki_binding: str
    zk_fingerprint_seal: str
    neurallink_zeta_seal: str
    timestamp: str


class MITRadarKernelRegistry:
    """Registry for all 24 pages of the MIT RADAR PDP-8/IX Timesharing Kernel.
    Each page is cryptographically bound to TPM-119 and Zain Kauser's identity."""

    def __init__(self):
        self.pages: List[KernelPage] = []
        self.cumulative_chain_hash: str = ""
        self.master_binding_seal: str = ""
        self._loaded = False

    def load_from_bindings(self, bindings_file: str) -> None:
        """Load page bindings from the TPM-119 binding JSON file."""
        with open(bindings_file, "r") as f:
            data = json.load(f)

        for pb in data["page_bindings"]:
            page = KernelPage(
                page_index=pb["page_index"],
                filename=pb["filename"],
                file_size_bytes=pb["file_size_bytes"],
                sha512_hash=pb["sha512_page_hash"],
                tpm119_pcr_extension=pb["tpm119_pcr_extension"],
                dod_pki_binding=pb["dod_pki_binding"],
                zk_fingerprint_seal=pb["zk_fingerprint_seal"],
                neurallink_zeta_seal=pb["neurallink_zeta_seal"],
                timestamp=pb["timestamp"],
            )
            self.pages.append(page)

        self.cumulative_chain_hash = data["cumulative_chain_hash"]
        self.master_binding_seal = data["master_binding_seal"]
        self._loaded = True

    def verify_page_integrity(self, page_index: int, jp2_dir: str) -> bool:
        """Verify a single page's SHA-512 hash against the stored binding."""
        if not self._loaded or page_index >= len(self.pages):
            return False
        page = self.pages[page_index]
        filepath = os.path.join(jp2_dir, page.filename)
        if not os.path.exists(filepath):
            return False
        with open(filepath, "rb") as f:
            computed = hashlib.sha512(f.read()).hexdigest()
        return computed == page.sha512_hash

    def verify_all_pages(self, jp2_dir: str) -> Dict[int, bool]:
        """Verify all 24 pages against their stored bindings."""
        results = {}
        for page in self.pages:
            results[page.page_index] = self.verify_page_integrity(
                page.page_index, jp2_dir
            )
        return results

    def get_master_seal(self) -> str:
        """Return the master binding seal for the entire kernel archive."""
        return self.master_binding_seal


