def main(scan_paths: list = None, directive: str = None, output_path: str = None,
         custom_patterns: dict = None, output_prefix: str = "orbital_forensics"):
    """
    ADAPTIVE MAIN — accepts any paths, any directive, any output location.
    Not gridlocked to previous files. Adapts upon order.

    Args:
        scan_paths:      List of paths (files, directories, globs) to scan.
                         If None, scans current working directory.
        directive:       Custom Dr. Einstein directive text. If None, uses default.
        output_path:     Directory for output files. Defaults to /home/ubuntu.
        custom_patterns: Dict of additional regex patterns for entity extraction.
        output_prefix:   Prefix for output filenames.
    """
    if output_path is None:
        output_path = "/home/ubuntu"
