    print(f"\n{'=' * 80}")
    print("  FINAL TPM-119 PCR[0-23] SEAL")
    print(f"{'=' * 80}")
    print(f"  Total Extensions: {final_pki['extensions']}")
    print(f"  Final Handshake: {final_pki['handshake_id']}")
    print(f"  Final PCR Chain: {final_pki['pcr_chain_hash']}")

    # -- Save Master Report JSON --
