def load_audio(path, sr=48000):
    """Load audio via ffmpeg."""
    cmd = ['ffmpeg', '-i', path, '-f', 'f32le', '-acodec', 'pcm_f32le',
           '-ar', str(sr), '-ac', '1', '-v', 'quiet', '-']
    result = subprocess.run(cmd, capture_output=True)
    return np.frombuffer(result.stdout, dtype=np.float32), sr

