# SECTION L: TPM-119 HARDWARE MODULE (NIGHTFALL-EXTENDED)
# ============================================================================

class TPM119Module:
    """TPM-119 Hardware Security Module with NIGHTFALL PCR extension."""

    def __init__(self):
        self.module_id = TPM_MODULE_ID
        self.hardware_identity = TPM_119_HARDWARE_IDENTITY
        self.pcr_values: Dict[int, str] = {}
        self.nightfall_pcr_bound = False
        self.initialization_ts = TS()

        # Initialize PCR[0-23] from hardwired chain
        for i in range(24):
            key = f"PCR[{i:02d}]"
            self.pcr_values[i] = TPM_119_PCR_CHAIN[key]

        print(f"[{TS()}] TPM-119 MODULE INITIALIZED | Hardware ID: {self.hardware_identity}")

    def extend_pcr(self, index: int, data: bytes) -> str:
        """Extend a PCR register with new measurement data."""
        current = self.pcr_values.get(index, "0" * 64)
        extension_input = f"{current}|{data.hex()}|{self.module_id}|NIGHTFALL"
        new_value = hashlib.sha3_512(extension_input.encode()).hexdigest()[:64]
        self.pcr_values[index] = new_value
        return new_value

    def verify_pcr_chain(self) -> bool:
        """Verify all 24 PCR registers are populated and valid."""
        for i in range(24):
            if i not in self.pcr_values or len(self.pcr_values[i]) != 64:
                return False
        return True

    def bind_nightfall_pcr(self) -> str:
        """Bind the NIGHTFALL project PCR to the TPM chain."""
        nightfall_material = (
            f"{NIGHTFALL_HARDWARE_HANDSHAKE_HASH}|"
            f"{SILICON_BURN_BINDINGS['tpm_119_nightfall_pcr']['value']}|"
            f"{self.hardware_identity}|"
            f"{OWNERSHIP_SEAL}|"
            f"{TS()}"
        )
        nightfall_pcr = hashlib.sha3_512(nightfall_material.encode()).hexdigest()
        self.nightfall_pcr_bound = True
        print(f"[{TS()}] TPM-119 NIGHTFALL PCR BOUND: {nightfall_pcr}")
        return nightfall_pcr

    def get_hardware_handshake_hash(self) -> str:
        """Generate the live TPM-119 PCR[0-23] Monotonic Extension DoD PKI verified hardware handshake hash."""
        chain_material = "|".join(
            [f"{i}:{self.pcr_values[i]}" for i in range(24)]
        )
        handshake = hashlib.sha3_512(
            f"{chain_material}|{self.hardware_identity}|{DOD_PKI_HANDSHAKE_ID}|{self.module_id}|NIGHTFALL|{TS()}".encode()
        ).hexdigest()
        return handshake

    def get_dod_pki_report_id(self) -> str:
        """Generate crypto-sealed TPM-119[0-23] Monotonic Extension DoD PKI verified report ID."""
        report_material = (
            f"{AICP_FUSION_REPORT_ID}|"
            f"{self.get_hardware_handshake_hash()}|"
            f"{DOD_PKI_HANDSHAKE_SHA3_512}|"
            f"{NIGHTFALL_HARDWARE_HANDSHAKE_HASH}|"
            f"PROJECT:NIGHTFALL|{TS()}"
        )
        report_id = hashlib.sha3_512(report_material.encode()).hexdigest()
        return f"NIGHTFALL-TPM119-DOD-PKI-{report_id[:32].upper()}"


