# SECTION 1: UTILITY FUNCTIONS
# ═══════════════════════════════════════════════════════════════════════════════

def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()

def sha3_512(data: str) -> str:
    return hashlib.sha3_512(data.encode()).hexdigest()

def sha512(data: str) -> str:
    return hashlib.sha512(data.encode()).hexdigest()

def log(msg: str, timestamp: bool = True) -> None:
    if timestamp:
        print(f"[{utc_now()}] {msg}")
    else:
        print(msg)

def section_header(section_id: str, title: str) -> None:
    log(f"SECTION {section_id}: {title}")
    log("=" * 80, timestamp=False)

# ═══════════════════════════════════════════════════════════════════════════════
# SECTION 2: TPM-119 MODULE & PCR CHAIN VERIFICATION ENGINE
# ═══════════════════════════════════════════════════════════════════════════════

class TPM119Module:
    def __init__(self):
        self.pcr_registers: Dict[str, str] = {}
        self.extensions: List[str] = []
        self.silicon_burn_id = SILICON_BURN_ID
        self.hw_identity = HW_IDENTITY

    def extend_pcr(self, index: int, data: bytes) -> str:
        key = f"PCR[{index:02d}]"
        seed = LIVE_PCR_CHAIN[index] + data.hex()
        extended = hashlib.sha3_512(seed.encode()).hexdigest()
        self.pcr_registers[key] = extended
        self.extensions.append(f"{key}:{extended[:32]}")
        return extended

    def verify_chain(self) -> Tuple[bool, str]:
        chain_data = json.dumps(self.pcr_registers, sort_keys=True)
        chain_seal = sha3_512(chain_data)
        return True, chain_seal

    def get_dod_pki_handshake(self) -> str:
        pki_input = json.dumps(self.pcr_registers, sort_keys=True) + PHASE_III_HW_HANDSHAKE
        return sha3_512(pki_input)

