def start_vpn_tunnel(vpn_config: dict) -> dict:
          """
          Start OpenVPN tunnel with credentials inline.
          """
          result = {"endpoint": vpn_config["endpoint"], "status": "failed"}
          try:
                    cmd = [
                              "openvpn",
                              f"--remote={vpn_config['ip']}",
                              f"--port={vpn_config['port']}",
                              "--dev", "tun0",
                              "--proto", "udp",
                              "--auth-user-pass"
                    ]
                    # Write creds to a temp file
                    creds_file = "/tmp/openvpn_auth.txt"
                    with open(creds_file, "w") as f:
                              f.write(f"{vpn_config['auth']['username']}\n{vpn_config['auth']['password']}\n")
 
                    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                    result["status"] = "started"
                    result["pid"] = proc.pid
                    logger.info(f"🔐 VPN tunnel started → {vpn_config['endpoint']} (PID={proc.pid})")
 
          except Exception as e:
                    logger.error(f"❌ VPN tunnel failed → {vpn_config['endpoint']} | {str(e)}")
                    result["error"] = str(e)
 
          return result
 
 
def run_vpn_tunnels():
          """
          Start all VPN tunnels (bound to TPM enclaves).
          """
          vpn_results = []
          for vpn in NASA_TELEMETRY_CONFIG_7D["vpn_tunnels"]:
                    vpn_results.append(start_vpn_tunnel(vpn))
          return vpn_results
 
