import sqlite3
 
DB_FILE = "telemetry_log.sqlite"
 
def init_db():
          """Initialize SQLite database for telemetry logging (Pythonista-safe)."""
          conn = sqlite3.connect(DB_FILE)
          cursor = conn.cursor()
          cursor.execute("""
                    CREATE TABLE IF NOT EXISTS telemetry (
                              id INTEGER PRIMARY KEY AUTOINCREMENT,
                              timestamp TEXT,
                              cycle_id INTEGER,
                              uplink_id TEXT,
                              endpoint TEXT,
                              freq TEXT,
                              strength TEXT,
                              objects TEXT,
                              status TEXT
                    )
          """)
          conn.commit()
          conn.close()
          logger.info("✅ SQLite database initialized (7E)")
 
def persist_telemetry_db(cycle_log: dict):
          """
          Save telemetry results to SQLite.
          Replaces psycopg2 → works natively on iOS/Pythonista.
          """
          try:
                    conn = sqlite3.connect(DB_FILE)
                    cursor = conn.cursor()
 
                    telemetry = cycle_log.get("telemetry", {})
                    cursor.execute("""
                              INSERT INTO telemetry (timestamp, cycle_id, uplink_id, endpoint, freq, strength, objects, status)
                              VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                    """, (
                              cycle_log.get("timestamp"),
                              cycle_log.get("cycle_id"),
                              cycle_log.get("uplink_id"),
                              cycle_log.get("endpoint"),
                              telemetry.get("freq"),
                              telemetry.get("strength"),
                              ",".join(telemetry.get("objects", [])) if telemetry.get("objects") else "",
                              telemetry.get("status")
                    ))
 
                    conn.commit()
                    logger.info("📥 Telemetry persisted to SQLite (7E)")
          except Exception as e:
                    logger.error(f"❌ SQLite logging failed (7E): {str(e)}")
          finally:
                    if conn:
                              conn.close()
 
