import socket, logging, requests
 
logger = logging.getLogger("USSS-APPLE-2025-PART-7G")
 
def fetch_radio_emissions(uplink: dict, enclave: dict) -> dict:
          """
          Capture live radio emissions from TPM-enabled uplinks.
          Includes freq, strength, modulation, bandwidth, noise floor,
          SNR/BER, latency, and status.
          """
          emissions = {
                    "uplink_id": uplink.get("id", "unknown"),
                    "endpoint": uplink.get("endpoint", uplink.get("ip")),
                    "tpm_binding": {
                              "chip": enclave["TPMChipID"],
                              "mac": enclave["MACAddress"],
                              "ip": enclave["IPAddress"]
                    },
                    "telemetry": {}
          }
 
          try:
                    if uplink.get("protocol") in ("http", "https"):
                              url = f"{uplink['protocol']}://{uplink['ip']}:{uplink['port']}/radio"
                              resp = requests.get(url, timeout=10, verify=False)
                              resp.raise_for_status()
                              data = resp.json()
 
                              emissions["telemetry"] = {
                                        "freq": data.get("FREQ"),
                                        "strength": data.get("STRENGTH"),
                                        "modulation": data.get("MODULATION"),
                                        "bandwidth": data.get("BANDWIDTH"),
                                        "noise_floor": data.get("NOISE_FLOOR"),
                                        "snr": data.get("SNR"),
                                        "ber": data.get("BER"),
                                        "latency": data.get("LATENCY"),
                                        "status": data.get("STATUS", "active")
                              }
 
                    elif uplink.get("protocol") == "tcp":
                              with socket.create_connection((uplink["ip"], uplink["port"]), timeout=5) as s:
                                        s.sendall(b"RADIO_EMISSIONS\n")
                                        raw = s.recv(8192).decode(errors="ignore")
                                        parsed = {}
                                        for token in raw.split():
                                                  if "=" in token:
                                                            k, v = token.split("=", 1)
                                                            parsed[k.strip().lower()] = v.strip()
 
                                        emissions["telemetry"] = {
                                                  "freq": parsed.get("freq"),
                                                  "strength": parsed.get("strength"),
                                                  "modulation": parsed.get("modulation"),
                                                  "bandwidth": parsed.get("bandwidth"),
                                                  "noise_floor": parsed.get("noise_floor"),
                                                  "snr": parsed.get("snr"),
                                                  "ber": parsed.get("ber"),
                                                  "latency": parsed.get("latency"),
                                                  "status": parsed.get("status", "active")
                                        }
 
          except Exception as e:
                    logger.error(f"❌ Radio emissions fetch failed for {uplink.get('endpoint')}: {str(e)}")
                    emissions["telemetry"]["status"] = "unreachable"
 
          return emissions
 
 
def runtime_cycle_with_radio(idx: int, runtime_certs: dict) -> dict:
          """
          Run one cycle that includes radio emissions monitoring.
          """
          cycle_log = runtime_cycle_verified(idx, runtime_certs)     # from Final Patch
 
          enclave = TPM_ENCLAVES[idx % len(TPM_ENCLAVES)]
          uplink = REACHABLE_UPLINKS[idx % len(REACHABLE_UPLINKS)]
 
          radio_data = fetch_radio_emissions(uplink, enclave)
          cycle_log["radio_emissions"] = radio_data
 
          logger.info(
                    f"🛰️📡 7G Cycle {idx} complete | "
                    f"Uplink={uplink['endpoint']} | "
                    f"Status={cycle_log['connection_status']}"
          )
 
          return cycle_log
    
