def hawking_temperature(M):
    """T_H = ℏc³ / (8πGMk_B)"""
    return (HBAR * C**3) / (8 * math.pi * G * M * K_B)

def hawking_power(M):
    """P = ℏc⁶ / (15360πG²M²)"""
    return (HBAR * C**6) / (15360 * math.pi * G**2 * M**2)

def schwarzschild_radius(M):
    """r_s = 2GM/c²"""
    return (2 * G * M) / C**2

def bekenstein_hawking_entropy(M):
    """S = 4πGM²k_B / (ℏc)"""
    return (4 * math.pi * G * M**2 * K_B) / (HBAR * C)

def evaporation_time(M):
    """t_ev = 5120πG²M³ / (ℏc⁴)"""
    return (5120 * math.pi * G**2 * M**3) / (HBAR * C**4)

def peak_wavelength(T):
    """Wien's law: λ_max = b/T where b = 2.898e-3 m·K"""
    return 2.898e-3 / T if T > 0 else float('inf')

