    r_s = schwarzschild_radius(mass)
    S = bekenstein_hawking_entropy(mass)
    t_ev = evaporation_time(mass)
    lam = peak_wavelength(T)
    
    entry = {
        "object": name,
        "mass_kg": mass,
        "hawking_temp_K": T,
        "luminosity_W": P,
        "schwarzschild_radius_m": r_s,
        "entropy_J_per_K": S,
        "evaporation_time_s": t_ev,
        "peak_wavelength_m": lam
    }
    hawking_data.append(entry)
    
    print(f"[{TS()}] │ {name}")
    print(f"[{TS()}] │   T_H = {T:.6e} K | P = {P:.6e} W | r_s = {r_s:.6e} m")
    print(f"[{TS()}] │   S_BH = {S:.6e} J/K | t_ev = {t_ev:.6e} s | λ_peak = {lam:.6e} m")

