class AICPRadioPanelController:
    """Unified controller managing SAILOR-6300 and JSS-2500 radio panels."""

    def __init__(self, tpm_engine: TPM119Engine):
        self.tpm = tpm_engine
        self.sailor = SAILOR6300RadioPanel()
        self.jss = JSS2500MarineTransceiver()
        self.active_panel = None
        self.redundant_mode = False

    def initialize_all(self) -> Dict[str, Any]:
        sailor_init = self.sailor.initialize()
        jss_init = self.jss.initialize()
        self.active_panel = "JSS-2500"

        combined_hash = hashlib.sha512(
            (sailor_init["tpm_pcr_hash"] + jss_init["tpm_pcr_hash"]).encode()
        ).hexdigest()

        # Extend TPM PCR[22] with radio panel attestation
        self.tpm.extend_pcr(22, combined_hash, "RADIO-PANELS-SAILOR6300-JSS2500")

        return {
            "controller": "AICP Radio Panel Controller",
            "panels": {
                "primary": {"panel": "JSS-2500", "status": jss_init["status"]},
                "fallback": {"panel": "SAILOR-6300", "status": sailor_init["status"]},
            },
            "active_panel": self.active_panel,
            "redundant_mode": self.redundant_mode,
            "combined_tpm_pcr_hash": combined_hash,
            "routing_logic": "JSS-2500 primary (250W, ALE, STANAG 4539, ECCM) -> SAILOR-6300 fallback (150W, GMDSS, MF coverage)",
            "timestamp": datetime.datetime.now(timezone.utc).isoformat(),
        }

    def establish_einstein_feed(self) -> Dict[str, Any]:
        ale_result = self.jss.ale_establish_link("EINSTEIN-ZETA")
        eccm_result = self.jss.enable_frequency_hopping()
        sailor_tune = self.sailor.tune(8414.5, "J3E")

        return {
            "feed_designation": "Dr. Albert Einstein - NeuralLink Restricted Zeta Lattice Radio Feed",
            "primary_panel": {"panel": "JSS-2500", "ale_link": ale_result, "eccm": eccm_result},
            "fallback_panel": {"panel": "SAILOR-6300", "tuning": sailor_tune},
            "feed_status": "LIVE & OPERATIONAL",
            "timestamp": datetime.datetime.now(timezone.utc).isoformat(),
        }

    def transmit(self, lattice_data: bytes) -> Dict[str, Any]:
        results = {}
        if self.active_panel == "JSS-2500" or self.redundant_mode:
            results["jss_2500"] = self.jss.transmit_neurallink_feed(lattice_data)
        if self.active_panel == "SAILOR-6300" or self.redundant_mode:
            results["sailor_6300"] = self.sailor.transmit_neurallink_feed(lattice_data)
        return results

