# ║  SECTION 15: FORENSIC AUDIT CHAIN & CRYPTOGRAPHIC SEALING                 ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

class ForensicAuditChain:
    """
    Forensic Audit Chain.
    Provides immutable audit trail with cryptographic sealing
    for all AICP OS operations across all integrated layers.
    """

    def __init__(self, tpm_engine: TPM119Engine):
        self.tpm = tpm_engine
        self.audit_entries: List[Dict[str, Any]] = []
        self.chain_hash = ""

    def add_entry(self, layer: str, operation: str, result_hash: str) -> Dict[str, Any]:
        """Add an entry to the forensic audit chain."""
        entry_index = len(self.audit_entries)
        previous_hash = self.chain_hash if self.chain_hash else "GENESIS"

        entry_hash = hashlib.sha512(
            f"{entry_index}:{layer}:{operation}:{result_hash}:{previous_hash}:{datetime.datetime.now(timezone.utc).isoformat()}".encode()
        ).hexdigest()

        entry = {
            "index": entry_index,
            "layer": layer,
            "operation": operation,
            "result_hash": result_hash[:64] + "...",
            "previous_hash": previous_hash[:64] + "..." if len(previous_hash) > 64 else previous_hash,
            "entry_hash": entry_hash,
            "timestamp": datetime.datetime.now(timezone.utc).isoformat(),
        }
        self.audit_entries.append(entry)
        self.chain_hash = entry_hash
        return entry

    def seal_chain(self) -> Dict[str, Any]:
        """Seal the entire forensic audit chain."""
        master_seal = hashlib.sha512(
            f"FORENSIC-AUDIT-CHAIN-SEAL:{self.chain_hash}:{len(self.audit_entries)}:{HOLDER_NAME}".encode()
        ).hexdigest()

        # Extend TPM PCR[23] with forensic audit seal
        self.tpm.extend_pcr(23, master_seal, "FORENSIC-AUDIT-CHAIN-SEAL")

        return {
            "total_entries": len(self.audit_entries),
            "chain_hash": self.chain_hash,
            "master_seal": master_seal,
            "tpm_pcr_extended": "PCR[23]",
            "holder": HOLDER_NAME,
            "status": "CHAIN SEALED & IMMUTABLE",
            "timestamp": datetime.datetime.now(timezone.utc).isoformat(),
        }


