# MANDATE EXECUTION LEDGER
# ═══════════════════════════════════════════════════════════════════════════════

class MandateExecutionLedger:
    """Immutable, TPM-signed execution ledger for all mandate operations."""

    def __init__(self):
        self.entries: List[Dict] = []
        self.pcr_register = "0" * 64  # PCR-23 initial state

    def record(self, directive: int, operation: str, status: str, details: Dict):
        entry = {
            "index": len(self.entries),
            "directive": directive,
            "operation": operation,
            "status": status,
            "details": details,
            "timestamp": _ts(),
            "pcr_before": self.pcr_register
        }

        # Extend PCR with this entry
        entry_bytes = json.dumps(entry, sort_keys=True).encode()
        self.pcr_register = _pcr_extend(self.pcr_register, entry_bytes)
        entry["pcr_after"] = self.pcr_register

        # Sign the entry
        entry["signature"] = _tpm_sign(entry_bytes).hex()[:64]

        self.entries.append(entry)
        return entry

    def seal(self) -> Dict:
        payload = json.dumps(self.entries, sort_keys=True).encode()
        seal_sig = _tpm_sign(payload)
        return {
            "total_entries": len(self.entries),
            "final_pcr": self.pcr_register,
            "seal_signature": seal_sig.hex()[:64],
            "seal_verified": _tpm_verify(payload, seal_sig),
            "timestamp": _ts()
        }


