class MITRADARKernelScanner:
    """MIT RADAR PDP-8/IX Timesharing Kernel - adaptive forensic document scanner.
    Accepts ANY text file, ANY image directory, ANY code file. Not gridlocked."""

    PDP8_OPCODES = {
        "AND": 0o0000, "TAD": 0o1000, "ISZ": 0o2000, "DCA": 0o3000,
        "JMS": 0o4000, "JMP": 0o5000, "IOT": 0o6000, "OPR": 0o7000
    }

    PAL8_SYMBOLS = [
        "CLA", "CLL", "CMA", "CML", "RAR", "RAL", "RTR", "RTL",
        "IAC", "SMA", "SZA", "SNL", "SPA", "SNA", "SZL", "SKP",
        "OSR", "HLT", "MQL", "MQA", "CAM", "SWP", "ACL", "MUY",
        "DVI", "NMI", "SHL", "ASR", "LSR", "SCA", "DAD", "DST", "SWBA"
    ]

    # Adaptive entity patterns - loaded dynamically, extendable at runtime
    DEFAULT_ENTITY_PATTERNS = {
        "names": [r'\b([A-Z][a-z]+(?:\s+[A-Z][a-z]+)+)\b'],
        "ranks": [
            r'\b(SS[-\s]?(?:Oberst|Haupt|Sturm|Unter|Ober)(?:gruppen|sturm|bann|schar)?f(?:ue|u)hrer)\b',
            r'\b(Kommandant|Lagerkommandant|Lagerf[uu]hrer)\b',
            r'\b(Oberst|Major|General|Hauptmann|Leutnant|Feldwebel)\b',
            r'\b(Colonel|Captain|Lieutenant|Sergeant|Private|Corporal)\b',
            r'\b(Gestapo|Wehrmacht|Waffen[- ]SS|RSHA|WVHA|SD)\b',
        ],
        "locations": [
            r'\b(Auschwitz|Birkenau|Buchenwald|Dachau|Treblinka|Sobibor|Majdanek|Bergen[- ]Belsen)\b',
            r'\b(Ravensbr[uu]ck|Sachsenhausen|Mauthausen|Flossenburg|Natzweiler|Stutthof|Neuengamme)\b',
            r'\b(Gross[- ]Rosen|Papenburg|Esterwegen|Oranienburg|Gusen|Theresienstadt)\b',
            r'\b(Nuremberg|N[uu]rnberg|Berlin|Munich|M[uu]nchen|Hamburg|Warsaw|Krakow|Prague)\b',
            r'\b(Poland|Germany|Austria|Czechoslovakia|France|Netherlands|Belgium|Hungary)\b',
        ],
        "crimes": [
            r'\b(murder|mass murder|killing|execution|extermination|genocide)\b',
            r'\b(torture|cruelty|ill[- ]treatment|maltreatment|abuse)\b',
            r'\b(war crime|crime against humanity|crime against peace)\b',
            r'\b(deportation|forced labor|slave labor|starvation)\b',
            r'\b(medical experiment|sterilization|euthanasia)\b',
            r'\b(plunder|looting|confiscation|destruction)\b',
        ],
        "references": [
            r'\b([A-Z]{2,5}[-/]\d{2,6})\b',
            r'\b(Case\s+(?:No\.?\s*)?\d+)\b',
            r'\b(List\s+(?:No\.?\s*)?\d+)\b',
            r'\b(Reel\s+\d+)\b',
        ],
        "dates": [
            r'\b(\d{1,2}[./]\d{1,2}[./]\d{2,4})\b',
            r'\b(\d{4})\b',
        ],
    }

    def __init__(self, tpm: TPM119MonotonicExtension, custom_patterns: dict = None):
        self.tpm = tpm
        self.scan_id = f"RADAR-SCAN-{secrets.token_hex(8).upper()}"
        self.total_scans = 0
        self.findings = []
        self.entity_registry = defaultdict(list)
        self.frequency_tables = {}
        # Merge custom patterns with defaults — adaptive upon order
        self.entity_patterns = dict(self.DEFAULT_ENTITY_PATTERNS)
        if custom_patterns:
            for key, patterns in custom_patterns.items():
                if key in self.entity_patterns:
                    self.entity_patterns[key].extend(patterns)
                else:
                    self.entity_patterns[key] = patterns

    def add_patterns(self, category: str, patterns: list):
        """Runtime injection of new entity patterns — adaptive, not gridlocked."""
        if category in self.entity_patterns:
            self.entity_patterns[category].extend(patterns)
        else:
            self.entity_patterns[category] = patterns

    def _extract_entities(self, content: str) -> dict:
        """Extract all entities using the current (adaptive) pattern set."""
        entities = {}
        for category, patterns in self.entity_patterns.items():
            found = []
            for pattern in patterns:
                try:
                    found.extend(re.findall(pattern, content, re.IGNORECASE))
                except re.error:
                    pass
            freq = Counter(found)
            entities[category] = {
                "items": dict(freq.most_common(50)),
                "unique_count": len(set(found)),
                "total_count": len(found),
            }
        return entities

    def _detect_anomalies(self, content: str, lines: list, total_words: int) -> list:
        """Detect anomalies — redactions, high-density registries, tabular structures."""
        anomalies = []

        redacted = re.findall(r'\[(?:REDACTED|CENSORED|CLASSIFIED|DELETED)\]', content, re.IGNORECASE)
        if redacted:
            anomalies.append({"type": "REDACTION_MARKERS", "count": len(redacted)})

        prisoner_nums = re.findall(r'\b(\d{4,7})\b', content)
        if len(prisoner_nums) > 50:
            anomalies.append({"type": "HIGH_NUMERICAL_DENSITY", "count": len(prisoner_nums),
                            "note": "Potential prisoner number registry or encoded data"})

        all_names = re.findall(r'\b([A-Z][a-z]+(?:\s+[A-Z][a-z]+)+)\b', content)
        all_locs = []
        for lp in self.entity_patterns.get("locations", []):
            try:
                all_locs.extend(re.findall(lp, content, re.IGNORECASE))
            except re.error:
                pass
        entity_density = (len(set(all_names)) + len(set(all_locs))) / max(1, total_words / 1000)
        if entity_density > 10:
            anomalies.append({"type": "HIGH_ENTITY_DENSITY", "density": round(entity_density, 2),
                            "note": "Registry or index document"})

        tab_lines = sum(1 for l in lines if l.count("\t") > 2 or l.count("  ") > 3)
        total_lines = len(lines)
        if tab_lines > total_lines * 0.1:
            anomalies.append({"type": "TABULAR_STRUCTURE", "tab_lines": tab_lines,
                            "percentage": round(tab_lines / max(1, total_lines) * 100, 1)})

        return anomalies

    def scan_text_file(self, filepath: str) -> dict:
        """Deep forensic scan of ANY text file using MIT RADAR kernel analysis."""
        self.total_scans += 1
        scan_start = time.time()

        with open(filepath, "r", errors="replace") as f:
            content = f.read()

        filename = os.path.basename(filepath)
        lines = content.split("\n")
        total_lines = len(lines)
        total_chars = len(content)
        total_words = len(content.split())

        doc_hash = hashlib.sha3_512(content.encode()).hexdigest()
        entities = self._extract_entities(content)
        anomalies = self._detect_anomalies(content, lines, total_words)

        # Filter WWII-era years from dates
        date_items = entities.get("dates", {}).get("items", {})
        years_wwii = {y: c for y, c in date_items.items() if y.isdigit() and 1933 <= int(y) <= 1950}

        scan_time = time.time() - scan_start
        self.tpm.extend(8, f"RADAR_SCAN_{filename}_{doc_hash[:16]}")

        result = {
            "scan_id": f"{self.scan_id}-{self.total_scans:04d}",
            "scan_type": "TEXT",
            "file": filename,
            "file_path": filepath,
            "doc_hash_sha3_512": doc_hash,
            "metrics": {
                "total_lines": total_lines,
                "total_words": total_words,
                "total_chars": total_chars,
                "scan_time_s": round(scan_time, 4)
            },
            "entities": entities,
            "dates_wwii_years": years_wwii,
            "anomalies": anomalies,
            "tpm_pcr_8": self.tpm.pcr_bank["PCR_8"],
            "timestamp": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),

        }

        self.findings.append(result)
        return result

    def scan_code_file(self, filepath: str) -> dict:
        """Forensic scan of a code/script file — structure, imports, class/function inventory."""
        self.total_scans += 1
        scan_start = time.time()

        with open(filepath, "r", errors="replace") as f:
            content = f.read()

        filename = os.path.basename(filepath)
        lines = content.split("\n")
        doc_hash = hashlib.sha3_512(content.encode()).hexdigest()

        # Code-specific extraction
        classes = re.findall(r'^class\s+(\w+)', content, re.MULTILINE)
        functions = re.findall(r'^def\s+(\w+)', content, re.MULTILINE)
        imports = re.findall(r'^(?:import|from)\s+(\S+)', content, re.MULTILINE)
        comments = [l.strip() for l in lines if l.strip().startswith("#")]
        docstrings = re.findall(r'"""(.*?)"""', content, re.DOTALL)

        scan_time = time.time() - scan_start
        self.tpm.extend(9, f"CODE_SCAN_{filename}_{doc_hash[:16]}")

        result = {
            "scan_id": f"{self.scan_id}-{self.total_scans:04d}",
            "scan_type": "CODE",
            "file": filename,
            "file_path": filepath,
            "doc_hash_sha3_512": doc_hash,
            "metrics": {
                "total_lines": len(lines),
                "total_chars": len(content),
                "classes": len(classes),
                "functions": len(functions),
                "imports": len(imports),
                "comments": len(comments),
                "scan_time_s": round(scan_time, 4)
            },
            "structure": {
                "classes": classes,
                "functions": functions[:50],
                "imports": imports[:50],
                "docstrings_count": len(docstrings),
            },
            "anomalies": [],
            "tpm_pcr_9": self.tpm.pcr_bank["PCR_9"],
            "timestamp": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),

        }

        self.findings.append(result)
        return result

    def scan_image_directory(self, dirpath: str, archive_name: str = None) -> dict:
        """Scan an image directory — extract metadata, page count, structural analysis."""
        self.total_scans += 1
        scan_start = time.time()

        if not archive_name:
            archive_name = os.path.basename(dirpath)

        # Find all image files in directory
        image_files = []
        for ext in IMAGE_EXTENSIONS:
            image_files.extend(glob.glob(os.path.join(dirpath, f"*{ext}")))
        image_files = sorted(image_files)
        page_count = len(image_files)

        page_hashes = []
        page_sizes = []
        for img in image_files:
            with open(img, "rb") as f:
                data = f.read(8192)
                page_hashes.append(hashlib.sha3_512(data).hexdigest()[:32])
                page_sizes.append(os.path.getsize(img))

        dimensions = []
        try:
            from PIL import Image
            for img_path in image_files[:5]:
                try:
                    with Image.open(img_path) as im:
                        dimensions.append({"file": os.path.basename(img_path), "width": im.width, "height": im.height})
                except Exception:
                    pass
        except ImportError:
            pass

        total_size = sum(page_sizes)
        archive_hash = hashlib.sha3_512(
            "|".join(page_hashes).encode()
        ).hexdigest()

        scan_time = time.time() - scan_start
        self.tpm.extend(10, f"IMAGE_SCAN_{archive_name}_{archive_hash[:16]}")

        result = {
            "scan_id": f"{self.scan_id}-{self.total_scans:04d}",
            "scan_type": "IMAGE_DIR",
            "archive_name": archive_name,
            "dir_path": dirpath,
            "page_count": page_count,
            "total_size_bytes": total_size,
            "total_size_mb": round(total_size / 1024 / 1024, 2),
            "archive_hash_sha3_512": archive_hash,
            "page_hashes_sample": page_hashes[:10],
            "page_sizes_sample": page_sizes[:10],
            "dimensions_sample": dimensions,
            "avg_page_size_bytes": round(total_size / max(1, page_count)),
            "anomalies": [],
            "tpm_pcr_10": self.tpm.pcr_bank["PCR_10"],
            "timestamp": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),

        }

