def silicon_burn(component: str, domain: str, seed: str) -> str:
    """Generate unique silicon burn hash for a specific component in a domain."""
    raw = f"{MASTER_FUSION_SEAL}:{PLATFORM_ID}:{domain}:{component}:{seed}"
    return sha3_512(raw)

def silicon_burn_chain(components: list, domain: str) -> dict:
    """Chain silicon burns — each hash feeds into the next."""
    chain = {}
    prev = MASTER_FUSION_SEAL
    for comp in components:
        h = silicon_burn(comp, domain, prev)
        chain[comp] = h
        prev = h
    return chain

