for domain, data in IPAWS["domains"].items():
    burns = data["burns"]
    terminal = list(burns.values())[-1]
    ipaws_terminals[domain] = terminal

# Extract terminal hashes from each TRACS domain
tracs_terminals = {}
for domain, data in TRACS["domains"].items():
    burns = data["burns"]
    terminal = list(burns.values())[-1]
    tracs_terminals[domain] = terminal

# Cross-bind: each IPAWS domain terminal x each TRACS domain terminal
cross_bindings = {}
