# MONOTONIC COUNTER & ANTI-REPLAY
# ═══════════════════════════════════════════════════════════════════════════════

class MonotonicCounter:
    """TPM-119 Monotonic Counter — Anti-Replay Enforcement"""

    def __init__(self, initial_value: int = 847293104):
        self._value = initial_value
        self._history: List[Tuple[int, str]] = []

    @property
    def value(self) -> int:
        return self._value

    def increment(self, event: str) -> int:
        self._value += 1
        self._history.append((self._value, event))
        return self._value

    def verify_monotonic(self) -> bool:
        """Verify counter has never decremented"""
        for i in range(1, len(self._history)):
            if self._history[i][0] <= self._history[i-1][0]:
                return False
        return True

    def seal(self) -> Dict:
        """Generate monotonic seal for PCR extension"""
        seal_hash = hashlib.sha384(
            struct.pack(">Q", self._value) + b"SIGMA-001-MONOTONIC-SEAL"
        ).hexdigest()
        return {
            "counter": self._value,
            "seal_hash_sha384": seal_hash,
            "monotonic_verified": self.verify_monotonic(),
            "anti_replay": "ENFORCED",
            "timestamp": datetime.now(timezone.utc).isoformat(),
        }


