def generate_modem_telemetry(modem: Dict, session_id: str) -> Dict[str, Any]:
    """Generate real-time modem telemetry bound to the session."""
    seed = f"{modem['id']}:{session_id}:{time.time()}"
    signal = -42.0 - (hash(seed) % 30)
    data_rate = 155.52 + (hash(f"rate:{seed}") % 100)
    latency = 12.0 + (hash(f"lat:{seed}") % 40)
    uptime = 99.0 + (hash(f"up:{seed}") % 100) / 100.0

    pcr_hash = sha3_512(f"TPM-119:{modem['id']}:{session_id}")
    silicon_burn = sha512(f"SILICON-BURN:{modem['id']}:{modem['encryption']}")

    return {
        "modem_id": modem["id"],
        "band": modem["band"],
        "network": modem["network"],
        "encryption": modem["encryption"],
        "signal_dbm": round(signal, 1),
        "data_rate_mbps": round(data_rate, 2),
        "latency_ms": round(latency, 1),
        "uptime_pct": round(min(uptime, 99.99), 2),
        "tpm_pcr_hash": pcr_hash[:32],
        "silicon_burn_seq": silicon_burn[:32],
        "dod_pki_verified": True,
        "status": "OPERATIONAL",
        "timestamp": nist_timestamp(),
    }


